import{o as n,c as r,a0 as a,j as t,t as s,a as l,p as d}from"./chunks/framework.L_oL6aia.js";const c={class:"rock-copy-email-wrapper inline"},p=JSON.parse('{"title":"Midnight Rambler: User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"midnight-rambler.md","filePath":"midnight-rambler.md"}'),u={name:"midnight-rambler.md"},b=Object.assign(u,{setup(g){const o=d("Copy Email");function i(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="Copied!",setTimeout(function(){o.value="Copy Email"},2e3)}return(h,e)=>(n(),r("div",null,[e[1]||(e[1]=a('<h1 id="midnight-rambler-user-manual" tabindex="-1">Midnight Rambler: User Manual <a class="header-anchor" href="#midnight-rambler-user-manual" aria-label="Permalink to &quot;Midnight Rambler: User Manual&quot;">​</a></h1><p><strong>Version 1.0.1</strong></p><p>This manual provides a detailed description of the usage, design philosophy, and technical specifications for the <strong>Midnight Rambler</strong> amplifier emulation stompbox plugin.</p><img src="/midnightramblerinterface.png" alt="Midnight Rambler GUI" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><div style="display:flex;gap:0.75rem;justify-content:center;flex-wrap:wrap;margin:1.25rem 0 1.75rem 0;"><a href="/midnight-rambler-manual.pdf" download class="rock-btn rock-btn-secondary" style="display:inline-flex;align-items:center;justify-content:center;min-width:180px;padding:0.6rem 1.2rem;text-decoration:none;">Get PDF Manual (v1.0.1) 📄</a><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:220px;padding:0.6rem 1.4rem;text-decoration:none;">Download Plugin (FREE v1.0.1) ⬇️</a></div><hr><h2 id="_1-the-tweed-5e3-soul-a-studio-legend" tabindex="-1">1. The Tweed 5E3 Soul: A Studio Legend <a class="header-anchor" href="#_1-the-tweed-5e3-soul-a-studio-legend" aria-label="Permalink to &quot;1. The Tweed 5E3 Soul: A Studio Legend&quot;">​</a></h2><p>The <strong>Fender Tweed Deluxe 5E3</strong> (1950s) is widely regarded by producers and guitarists as the ultimate studio recording amplifier in rock history. Its simple 6V6 tube circuit delivers an unmistakable organic compression, warm harmonics, and touch-sensitive response that larger stadium amps cannot replicate.</p><p>From Keith Richards&#39; classic Rolling Stones rhythm crunch (<em>Sticky Fingers</em>, <em>Exile on Main St.</em>) and Neil Young&#39;s roaring grit to Billy Gibbons&#39; Texas blues bite and the legendary guitar tracks on <em>Hotel California</em>, the Tweed 5E3 shaped generations of iconic records.</p><h3 id="why-midnight-rambler-sets-a-new-standard" tabindex="-1">Why Midnight Rambler Sets a New Standard <a class="header-anchor" href="#why-midnight-rambler-sets-a-new-standard" aria-label="Permalink to &quot;Why Midnight Rambler Sets a New Standard&quot;">​</a></h3><p>Unlike static impulse responses or generic digital modeling plugins that feel stiff and sterile, Midnight Rambler captures the living, breathing acoustic soul of a boutique-calibrated Tweed 5E3:</p><ul><li><strong>True Neural Dynamics:</strong> Powered by cutting-edge Neural Amp Modeler (NAM) deep neural networks, responding seamlessly to your guitar&#39;s volume knob and picking dynamics.</li><li><strong>Intelligent Input Protection &amp; Noise Suppression:</strong> Built-in adaptive Noise Gate (-58 dBFS) and pre-NAM -0.1 dBFS analog waveshaper limiter ensure pristine signal integrity with zero background hiss.</li><li><strong>Mix-Ready Studio Suite:</strong> Independent post-amp State-Variable TPT filters (Bass HP &amp; Tone LP) combined with zero-latency 1971 Oxford 12&quot; studio cabinet convolution (Royer R121 ribbon and Shure SM57).</li><li><strong>Integrated Precision Chromatic Tuner:</strong> High-accuracy pitch engine with illuminated retro VU meter and dual detection algorithms (YIN / MPM).</li><li><strong>Zero Latency &amp; 100% Free:</strong> No accounts, no dongles, ultra-low CPU consumption. Plug in, turn up, and sound like a classic record immediately.</li></ul><hr><h2 id="_2-quick-control-guide" tabindex="-1">2. Quick Control Guide <a class="header-anchor" href="#_2-quick-control-guide" aria-label="Permalink to &quot;2. Quick Control Guide&quot;">​</a></h2><p>The plugin features 4 intuitive main knobs, 3 rotary switches, and an integrated chromatic tuner:</p><h3 id="🎛️-main-knobs" tabindex="-1">🎛️ Main Knobs <a class="header-anchor" href="#🎛️-main-knobs" aria-label="Permalink to &quot;🎛️ Main Knobs&quot;">​</a></h3><ul><li><strong>VOLUME / GAIN (<code>1.0</code> to <code>10.0</code>):</strong> Controls the input drive feeding the tube engine. Lower settings provide sparkling clean headroom; higher settings deliver thick vintage saturation and singing sustain.</li><li><strong>BASS (HP Filter · <code>20 Hz</code> to <code>300 Hz</code>):</strong> Tightens the low-end and eliminates unwanted sub-bass rumble, keeping rhythm tracks punchy.</li><li><strong>TONE (LP Filter · <code>1.0 kHz</code> to <code>20.0 kHz</code>):</strong> Controls top-end presence and smooths out harsh frequencies for a warm, woody character.</li><li><strong>MASTER (<code>1.0</code> to <code>10.0</code>):</strong> Clean linear output level with up to <code>+18 dB</code> of clean boost headroom.</li></ul><h3 id="🔀-selectors-switches" tabindex="-1">🔀 Selectors &amp; Switches <a class="header-anchor" href="#🔀-selectors-switches" aria-label="Permalink to &quot;🔀 Selectors &amp; Switches&quot;">​</a></h3><ul><li><strong>CHANNEL (Edge / Cranked):</strong><ul><li><strong>EDGE:</strong> Dynamic edge-of-breakup tone with ultra-sensitive pick response.</li><li><strong>CRANKED:</strong> Rich, saturated vintage overdrive with thick power-tube compression.</li></ul></li><li><strong>MIC / CAB (3-Way Rotary Switch · 1971 Oxford 12&quot; Studio Cabinet):</strong><ul><li><strong>WARM (9 o&#39;clock):</strong> Royer R121 ribbon microphone for a smooth, body-rich vintage response.</li><li><strong>SHARP (6 o&#39;clock):</strong> Shure SM57 dynamic microphone with bite and focused upper-mid punch.</li><li><strong>BLEND (3 o&#39;clock):</strong> Curated 60/40 studio combination (SM57 + R121) for balanced depth and realism.</li></ul></li><li><strong>STANDBY (Play / Mute):</strong> Instantly mutes audio output and drops CPU usage to <strong>0%</strong>.</li><li><strong>TUNER BUTTON (Top Right):</strong> Opens the integrated professional Chromatic Tuner overlay.</li><li><strong>Dynamic Background:</strong> Drag and drop any image file (<code>.jpg</code> or <code>.png</code>) directly onto the plugin window to change its skin on the fly.</li></ul><h3 id="📟-precision-chromatic-strobe-vu-tuner" tabindex="-1">📟 Precision Chromatic Strobe &amp; VU Tuner <a class="header-anchor" href="#📟-precision-chromatic-strobe-vu-tuner" aria-label="Permalink to &quot;📟 Precision Chromatic Strobe &amp; VU Tuner&quot;">​</a></h3><img src="/midnightramblertuner.png" alt="Midnight Rambler Chromatic Tuner" style="max-height:250px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><ul><li><strong>Illuminated Vintage VU Meter:</strong> Features smooth ballistic needle response indicating pitch deviation from <code>-50</code> to <code>+50 cents</code>. The center <code>0</code> mark illuminates in bright green when in tune.</li><li><strong>Dual Pitch Detection Engine:</strong><ul><li><strong>MPM (McLeod Pitch Method):</strong> Superior harmonic rejection, ideal for rich guitar signals and fast note acquisition.</li><li><strong>YIN:</strong> Industry-standard autocorrelation algorithm for ultra-precise fundamental frequency tracking.</li></ul></li><li><strong>Frequency &amp; Note Readout:</strong> Displays detected note name (e.g. <code>E2</code>, <code>A2</code>, <code>D3</code>, <code>G3</code>, <code>B3</code>, <code>E4</code>) and exact frequency in Hertz ($A4 = 440\\text{ Hz}$ concert pitch).</li><li><strong>Zero-CPU Sleep Architecture:</strong> When the tuner overlay is closed, its internal worker thread sleeps completely, guaranteeing <strong>0% CPU overhead</strong> during playback.</li></ul><hr><h2 id="_3-audio-configuration-standalone" tabindex="-1">3. Audio Configuration (Standalone) <a class="header-anchor" href="#_3-audio-configuration-standalone" aria-label="Permalink to &quot;3. Audio Configuration (Standalone)&quot;">​</a></h2><p>When running the pedal as a standalone application, configure your audio settings as follows for optimal performance:</p><ol><li><strong>Audio Device Type:</strong> Always select <strong>ASIO</strong> on Windows to avoid latency and digital distortion.</li><li><strong>Device:</strong> Select the native ASIO driver of your audio interface (e.g., <em>Focusrite USB ASIO</em>).</li><li><strong>Sample Rate:</strong> Set it to <strong>48000 Hz</strong> (48 kHz).</li><li><strong>Buffer Size:</strong> Set the buffer size to <strong>128 samples</strong> (2.3 ms) or <strong>256 samples</strong> (5.3 ms).</li></ol><h4 id="💡-the-buffer-phenomenon-why-256-samples-5-3-ms-might-sound-better-than-128-samples-2-3-ms" tabindex="-1">💡 The Buffer Phenomenon: Why 256 samples (5.3 ms) might sound better than 128 samples (2.3 ms) <a class="header-anchor" href="#💡-the-buffer-phenomenon-why-256-samples-5-3-ms-might-sound-better-than-128-samples-2-3-ms" aria-label="Permalink to &quot;💡 The Buffer Phenomenon: Why 256 samples (5.3 ms) might sound better than 128 samples (2.3 ms)&quot;">​</a></h4><p>Many guitarists experience a sweeter, more fluid tone at 256 samples. This is due to two factors:</p><ul><li><strong>Processor Stability:</strong> At 256 samples, the CPU processes audio chunks with more headroom, preventing micro-jitters that can introduce subtle treble harshness.</li><li><strong>Acoustic Duplication Effect:</strong> The tiny 5.3 ms delay, combined with the physical acoustic sound of your unplugged electric strings vibrating in the room, creates an organic doubling effect that adds tridimensional depth, thickness, and a natural room reverb feel to your playing.</li></ul><hr><h2 id="_4-system-requirements-distribution" tabindex="-1">4. System Requirements &amp; Distribution <a class="header-anchor" href="#_4-system-requirements-distribution" aria-label="Permalink to &quot;4. System Requirements &amp; Distribution&quot;">​</a></h2><h3 id="🖥️-system-requirements" tabindex="-1">🖥️ System Requirements <a class="header-anchor" href="#🖥️-system-requirements" aria-label="Permalink to &quot;🖥️ System Requirements&quot;">​</a></h3><ul><li><strong>Operating Systems</strong>: <ul><li><strong>Windows</strong>: Windows 10 or Windows 11 (64-bit).</li><li><strong>macOS</strong>: macOS 10.13 or newer (supports both Intel and Apple Silicon natively).</li><li><strong>Linux</strong>: Ubuntu 22.04 or compatible 64-bit distribution.</li></ul></li><li><strong>Processor (CPU)</strong>: Must support <strong>AVX2</strong> instruction sets (Intel Core 4th Gen / AMD Ryzen or newer) on Windows and Linux to calculate the mathematical models in real-time. Apple Silicon processors are fully supported natively.</li><li><strong>RAM</strong>: 4 GB minimum.</li><li><strong>Audio Card (Standalone mode)</strong>: Audio interface with low-latency drivers (native <strong>ASIO</strong> on Windows; <strong>CoreAudio</strong> on macOS; <strong>JACK</strong> or <strong>ALSA</strong> on Linux).</li></ul><h3 id="📦-distribution-all-in-one" tabindex="-1">📦 Distribution (All-in-One) <a class="header-anchor" href="#📦-distribution-all-in-one" aria-label="Permalink to &quot;📦 Distribution (All-in-One)&quot;">​</a></h3><p><strong>Midnight Rambler is 100% self-contained.</strong> It does not require loading external models, XML configs, or IR wav files separately:</p><ul><li>All neural amplifier models and cabinet profiles are <strong>embedded internally as binary resources</strong> inside the plugin binary.</li><li><strong>Windows</strong>: Simply copy the <code>.vst3</code> file to your plugin folder (typically <code>C:\\Program Files\\Common Files\\VST3\\</code>) or run the <code>.exe</code> standalone app.</li><li><strong>macOS</strong>: Copy the <code>.vst3</code> or <code>.component</code> (AU) to your plugin folder (typically <code>/Library/Audio/Plug-Ins/VST3/</code> or <code>/Library/Audio/Plug-Ins/Components/</code>) or run the <code>.app</code> standalone app.</li><li><strong>Linux</strong>: Copy the <code>.vst3</code> file to your plugin folder (typically <code>~/.vst3/</code> or <code>/usr/lib/vst3/</code>) or run the standalone binary.</li><li><strong>Direct Download</strong>: Get the latest multi-platform bundle from our <a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" rel="noreferrer">GitHub Releases</a>.</li></ul><div style="margin:1.25rem 0;text-align:center;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:250px;padding:0.65rem 1.6rem;text-decoration:none;font-size:1rem;">Download Midnight Rambler v1.0.1 (FREE) ⬇️</a></div><hr><h2 id="_5-troubleshooting" tabindex="-1">5. Troubleshooting <a class="header-anchor" href="#_5-troubleshooting" aria-label="Permalink to &quot;5. Troubleshooting&quot;">​</a></h2><h3 id="❌-the-vst3-does-not-appear-in-the-daw-or-fails-to-scan" tabindex="-1">❌ The VST3 does not appear in the DAW or fails to scan <a class="header-anchor" href="#❌-the-vst3-does-not-appear-in-the-daw-or-fails-to-scan" aria-label="Permalink to &quot;❌ The VST3 does not appear in the DAW or fails to scan&quot;">​</a></h3><ul><li><strong>Missing C++ Redistributable (Windows)</strong>: Although the plugin is statically compiled, some Windows installations might miss basic runtime components. Download and install the official <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft Visual C++ Redistributable 2015-2022 (x64)</a>.</li><li><strong>CPU Compatibility (AVX2)</strong>: Ensure your processor supports <strong>AVX2</strong> instructions (typically Intel Core 4th Gen / AMD Ryzen or newer). The underlying NAM neural engine requires AVX2 to compute neural networks in real-time on Windows and Linux. If your CPU lacks AVX2, the plugin will not load.</li><li><strong>Scan Path</strong>: Verify that your DAW is scanning the folder where you placed the <code>.vst3</code> file (e.g. <code>C:\\Program Files\\Common Files\\VST3\\</code> on Windows).</li></ul><h3 id="❌-standalone-app-shows-unidentified-developer-warning-macos" tabindex="-1">❌ Standalone App shows &quot;Unidentified Developer&quot; warning (macOS) <a class="header-anchor" href="#❌-standalone-app-shows-unidentified-developer-warning-macos" aria-label="Permalink to &quot;❌ Standalone App shows &quot;Unidentified Developer&quot; warning (macOS)&quot;">​</a></h3><ul><li><strong>Explanation</strong>: Because the plugin binaries are built via automated CI and not notarized with a paid Apple Developer Account, macOS may prevent them from launching.</li><li><strong>Solution</strong>: Go to <strong>System Settings &gt; Privacy &amp; Security</strong>, scroll down to the Security section, and click <strong>Open Anyway</strong> next to the warning for Midnight Rambler. Alternatively, open Terminal and run: <code>xattr -cr /path/to/MidnightRambler.app</code></li></ul><h3 id="❌-crackling-pops-or-high-latency-in-standalone-mode" tabindex="-1">❌ Crackling, pops, or high latency in Standalone mode <a class="header-anchor" href="#❌-crackling-pops-or-high-latency-in-standalone-mode" aria-label="Permalink to &quot;❌ Crackling, pops, or high latency in Standalone mode&quot;">​</a></h3><ul><li><strong>Audio Drivers</strong>: Ensure you are using the native low-latency driver for your audio interface (<strong>ASIO</strong> on Windows, <strong>CoreAudio</strong> on macOS, <strong>JACK</strong> or <strong>ALSA</strong> on Linux).</li><li><strong>Buffer Size</strong>: A buffer size of <strong>128</strong> or <strong>256 samples</strong> is recommended. Going lower than 64 samples might cause CPU spikes and audio crackle depending on your computer&#39;s performance.</li></ul><hr><h2 id="_6-license-terms-of-use" tabindex="-1">6. License &amp; Terms of Use <a class="header-anchor" href="#_6-license-terms-of-use" aria-label="Permalink to &quot;6. License &amp; Terms of Use&quot;">​</a></h2><p><strong>Midnight Rambler</strong> is distributed as <strong>Freeware (Closed-Source)</strong> under the <a href="/LICENSE.txt">Main St Audio Labs End User License Agreement (EULA)</a>:</p><ul><li><strong>Free Use:</strong> You are 100% free to use this plugin in any personal, educational, or commercial music production, mix, score, or live performance without paying any royalties or fees.</li><li><strong>Closed-Source Protection:</strong> Reverse engineering, decompiling, reselling, or charging for binary downloads is strictly prohibited. All rights and intellectual property belong exclusively to <em>Main St Audio Labs</em>.</li><li><strong>Disclaimer:</strong> The software is provided &quot;AS IS&quot;, without warranty of any kind. Third-party brand names (<em>Fender</em>, <em>Tweed Deluxe</em>, <em>5E3</em>, etc.) are used solely for descriptive and historical identification of tone.</li></ul><hr><h3 id="we-want-to-hear-your-mixes" tabindex="-1">We Want to Hear Your Mixes! <a class="header-anchor" href="#we-want-to-hear-your-mixes" aria-label="Permalink to &quot;We Want to Hear Your Mixes!&quot;">​</a></h3><p>Midnight Rambler&#39;s dynamic behavior was calibrated directly from classic record listening tests. If you&#39;ve recorded a song or mixed a track using this stompbox, we want to hear it!</p><p>Copy our contact email to share your links or feedback:</p>',53)),t("div",c,[e[0]||(e[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:i},s(o.value),1)]),e[2]||(e[2]=t("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"If you would like to support our independent research and help us keep our plugins free, you can support us with Card, PayPal, or Cryptocurrency:",-1)),e[3]||(e[3]=t("div",null,[t("a",{href:"/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Support the Lab (Ko-fi / Crypto) ☕")],-1)),e[4]||(e[4]=t("div",{class:"print-footer"},[l(" Official Website & Manual: "),t("a",{href:"https://mainstaudiolabs.github.io/midnight-rambler.html",target:"_blank"},"https://mainstaudiolabs.github.io/midnight-rambler.html")],-1))]))}});export{p as __pageData,b as default};
